import { describe, expect, it, vi } from 'vitest'
import { readFileSync } from 'node:fs'
import { evaluateExpression, evaluateFinish, foldLogs, nextWorkout, previewOfflineFinish } from './offline-finish.js'
import { createReppenStore } from './store.js'

// Generated by reppen-core backend/tests/workouts.rs against the real engine.
const fixture = JSON.parse(readFileSync(process.env.C3_EVIDENCE_PATH || new URL('./fixtures/finish-pack.json', import.meta.url), 'utf8'))
const num = v => ({ op: 'num', v })
const count = { op: 'agg', fn: 'count', sets: { slot: 's', step: 'w' } }
const pack = () => ({ format: 'reppen.residual/1', nodes: [{ plan: { day: 'A', slots: [] }, occurrences: [],
  finish: { k: 'residual', refuseIf: { op: 'eq', a: count, b: num(0) }, slots: [{ slot: 's', state: { load: { v: 'q', n: 100, dim: { mass: 1 }, unit: 'kg' } }, branches: [{ k: 'patch', when: { op: 'bool', v: true }, set: { load: { mode: 'commit', expr: { op: 'add', a: { op: 'at', sets: { slot: 's', step: 'w' }, i: 0, by: 'position', metric: 'load' }, b: num(2.5) }, dim: { mass: 1 }, unit: 'kg' } } }] }] },
  next: { k: 'workouts', outcomes: [{ slots: [0], needsConnection: "the next workout reads a value this workout's logs decide" }] } }] })
const log = { id: 'e1', kind: 'setLogged', slot: 's', step: 'w', set: 2, values: { load: 100, reps: 5 } }

describe('C3 data adapter', () => {
  it('folds corrections and clears; distinguishes logged positions from indexes', () => {
    const logs = foldLogs([log, { ...log, id: 'e2', values: { load: 105 } }])
    expect(evaluateExpression({ op: 'at', sets: { slot: 's', step: 'w' }, i: 0, by: 'position', metric: 'load' }, logs)).toBe(105)
    expect(evaluateExpression({ op: 'isNone', a: { op: 'at', sets: { slot: 's', step: 'w' }, i: 0, by: 'index', metric: 'load' } }, logs)).toBe(true)
    expect(evaluateFinish(pack(), 0, [log]).slots[0].state.load.n).toBe(102.5)
    expect(evaluateFinish(pack(), 0, [log, { ...log, id: 'clear', kind: 'setCleared' }])).toEqual({ k: 'refused', code: 'emptySession' })
  })
  it('preserves server connection fallbacks and refuses unknown operations or question patches', () => {
    const p = pack(), result = evaluateFinish(p, 0, [log])
    expect(nextWorkout(p, 0, result).reason).toContain('logs decide')
    p.nodes[0].finish.slots[0].branches[0].when = { op: 'runProgram', source: 'never executed' }
    expect(evaluateFinish(p, 0, [log]).k).toBe('needsConnection')
    const q = pack(); q.nodes[0].occurrences = [{}]
    expect(evaluateFinish(q, 0, [log]).k).toBe('needsConnection')
  })
  it('implements tolerant comparisons, lazy branches, empty aggregation and declared rounding', () => {
    expect(evaluateExpression({ op: 'eq', a: num(1), b: num(1 + 1e-10) }, [])).toBe(true)
    expect(evaluateExpression({ op: 'if', c: { op: 'bool', v: true }, a: num(7), b: { op: 'unknown' } }, [])).toBe(7)
    for (const [value, ties, expected] of [[3.75, 'up', 5], [3.75, 'down', 2.5], [-3.75, 'up', -2.5], [-3.75, 'down', -5]]) {
      expect(evaluateExpression({ op: 'round', a: num(value), step: 2.5, mode: 'nearest', ties }, [])).toBe(expected)
    }
    expect(evaluateExpression({ op: 'agg', fn: 'sum', sets: { slot: 's', step: 'w' }, of: { op: 'item', metric: 'load' } }, [])).toBe(0)
  })
  it('binds previews to workout, artifact, enrollment and exact revision', () => {
    const workout = { workoutId: 'w', artifactId: 'a', enrollmentId: 'e', revision: 0, events: [] }
    const envelope = { ...workout, workoutRevision: 0, pack: pack() }
    expect(previewOfflineFinish(envelope, workout, [log]).offlineState.s.load.n).toBe(102.5)
    for (const [key, value] of [['workoutId', 'other'], ['artifactId', 'other'], ['enrollmentId', 'other'], ['revision', 1]]) {
      expect(previewOfflineFinish(envelope, { ...workout, [key]: value }, [log]).finish.k).toBe('needsConnection')
    }
  })
  it('matches the real backend/core pack and supplies verified states through the existing store', async () => {
    const { envelope, events, finish, offlineState } = fixture
    expect(evaluateFinish(envelope.pack, 0, events)).toEqual(finish)
    const workout = { workoutId: envelope.workoutId, artifactId: envelope.artifactId, enrollmentId: envelope.enrollmentId, revision: envelope.workoutRevision, events, day: 'A1' }
    const client = { offlinePack: vi.fn(async () => envelope), finish: vi.fn(async () => ({ workout: { ...workout, status: 'completed' } })) }
    const kept = new Map()
    const storage = { getItem: k => kept.get(k) ?? null, setItem: (k,v) => kept.set(k,v) }
    const store = createReppenStore({ client, owner: () => 'owner', storage, today: () => '2026-10-05' })
    store.getState().hydrate()
    store.setState({ workout })
    await store.getState().loadOfflinePack()
    expect(store.getState().previewOfflineFinish().offlineState).toEqual(offlineState)
    expect(await store.getState().finish()).toBe(true)
    expect(client.finish).toHaveBeenCalledWith(envelope.workoutId, envelope.workoutRevision, offlineState)
  })
})
